-- Seed teams, cases, people, then Workstream B content.
-- Passcode hashes are NOT seeded here — set MEMBER_STARTER_CODE_HASH and
-- INITIAL_ADMIN_CODE_HASH in env; app sample-data path seeds locally.
-- Content files in supabase/seed/ are generated by: npx tsx scripts/seed-content.ts
-- Running this seed twice is a no-op (ON CONFLICT DO UPDATE / DO NOTHING).

on conflict (id) do update set name = excluded.name, colour = excluded.colour;

on conflict (id) do update set name = excluded.name, date = excluded.date, place = excluded.place;

-- Cases with stable IDs (content FKs depend on these).
on conflict (number) do update set
  title = excluded.title,
  active = excluded.active;

-- People (ids stable for docs). Jainam = tech_admin on Team 3. Dr. B = coach_admin.
on conflict (id) do nothing;

-- Workstream B content (generated). Apply after migrations including 00009.
\ir seed/00_cases_meta.sql
\ir seed/01_stakeholders.sql
\ir seed/02_claims.sql
\ir seed/03_truth_items.sql
\ir seed/04_questions.sql
\ir seed/05_opposing_and_one_pagers.sql
\ir seed/06_flashcards_roles_proposals.sql
\ir seed/07_scoring_card.sql
